CREATE OR REPLACE FUNCTION public.add_card_label(_card_id uuid,_name text,_color text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; lid uuid; BEGIN IF NOT public.can_access_card(_card_id) THEN RAISE EXCEPTION 'Card unavailable'; END IF; IF _color NOT IN ('green','yellow','orange','red','purple','blue','sky','lime','pink','teal','black') THEN RAISE EXCEPTION 'Invalid label color'; END IF; SELECT board_id INTO bid FROM public.cards WHERE id=_card_id; INSERT INTO public.labels(board_id,name,color) VALUES(bid,_name,_color) RETURNING id INTO lid; INSERT INTO public.card_labels(card_id,label_id) VALUES(_card_id,lid); RETURN lid; END $$;